class AppManager:
    def __init__(self, db_url: str, smtp_host: str, s3_bucket: str):
        import sqlite3, smtplib, boto3
        self.db = sqlite3.connect(db_url)
        self.smtp = smtplib.SMTP(smtp_host)
        self.s3 = boto3.client('s3')
        self.bucket = s3_bucket
        self.users: dict = {}
        self.cache: dict = {}

    def create_user(self, name: str, email: str) -> int:
        cursor = self.db.execute('INSERT INTO users (name,email) VALUES (?,?)', (name, email))
        self.db.commit()
        user_id = cursor.lastrowid
        self.users[user_id] = {'name': name, 'email': email}
        self.smtp.sendmail('noreply@app.com', email, f'Welcome {name}!')
        return user_id

    def upload_avatar(self, user_id: int, data: bytes) -> str:
